using System.ClientModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
services.AddSingleton<Notebook>();
services.AddSingleton<ResearchTools>();
services.AddHttpClient("search");

var openAiClient = new OpenAIClient(new ApiKeyCredential(apiKey));
services.AddChatClient(openAiClient.GetChatClient(modelId).AsIChatClient());

var provider = services.BuildServiceProvider();

var chatClient = provider.GetRequiredService<IChatClient>();
var researchTools = provider.GetRequiredService<ResearchTools>();
var notebook = provider.GetRequiredService<Notebook>();
var loggerFactory = provider.GetRequiredService<ILoggerFactory>();

var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync),
    AIFunctionFactory.Create(researchTools.FetchPageContentAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: "You are a research assistant. When given a topic, use the available tools to " +
        "search the web, read relevant pages, and take notes on key findings. " +
        "After gathering enough information (at least 2-3 sources), review your notes " +
        "and produce a concise summary of what you learned.",
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking",
    tools: tools,
    loggerFactory: loggerFactory,
    services: provider);

Console.WriteLine("Research Agent ready. Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var session = await agent.CreateSessionAsync();

    var chatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        MaxIterations = 15,
    };
    var runOptions = new ChatClientAgentRunOptions(chatOptions);

    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    await foreach (var update in agent.RunStreamingAsync(
        $"Research the following topic and summarize your findings: {topic}",
        session,
        runOptions))
    {
        if (!string.IsNullOrEmpty(update.Text))
        {
            Console.Write(update.Text);
        }
    }

    Console.WriteLine("\n");

    var notes = notebook.GetNotes();
    if (notes.Count > 0)
    {
        Console.WriteLine($"--- {notes.Count} note(s) saved during research ---");
    }
}

