         var request = new HttpRequestMessage(HttpMethod.Get, url);
         request.Headers.UserAgent.ParseAdd(
             "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

         var response = await client.SendAsync(request, cancellationToken);
         response.EnsureSuccessStatusCode();

         var html = await response.Content.ReadAsStringAsync(cancellationToken);

         return ParseSearchResults(html);
     }

     [Description("Fetch the text content of a web page given its URL. Returns the first ~3000 characters of visible text.")]
     public async Task<string> FetchPageContentAsync(
         [Description("The full URL of the page to fetch")] string url,
         CancellationToken cancellationToken = default)
     {
         if (!Uri.TryCreate(url, UriKind.Absolute, out var uri)
             || (uri.Scheme != "http" && uri.Scheme != "https"))
         {
             return "Invalid URL. Provide a full http or https URL.";
         }

         var client = CreateClient();
         var request = new HttpRequestMessage(HttpMethod.Get, uri);
         request.Headers.UserAgent.ParseAdd(
             "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

         try
         {
             var response = await client.SendAsync(request, cancellationToken);
             response.EnsureSuccessStatusCode();

             var html = await response.Content.ReadAsStringAsync(cancellationToken);
             var text = StripHtml(html);

             const int maxLength = 3000;
             return text.Length > maxLength ? text[..maxLength] + "\n[Content truncated]" : text;
         }
         catch (HttpRequestException ex)
         {
             return $"Failed to fetch page: {ex.Message}";
         }
     }

     private HttpClient CreateClient()
     {
         var client = _httpClientFactory.CreateClient("search");
         client.Timeout = TimeSpan.FromSeconds(15);
         return client;
     }

     private static List<SearchResult> ParseSearchResults(string html)
     {
         var results = new List<SearchResult>();

         var matches = ResultLinkRegex().Matches(html);
         foreach (Match match in matches)
         {
             var rawUrl = WebUtility.HtmlDecode(match.Groups["url"].Value);
             var title = WebUtility.HtmlDecode(StripHtmlTags(match.Groups["title"].Value)).Trim();

             // DuckDuckGo wraps URLs in a redirect; extract the actual URL.
             if (rawUrl.Contains("uddg="))
             {
                 var uddg = Uri.UnescapeDataString(
                     rawUrl.Split("uddg=")[1].Split('&')[0]);
                 rawUrl = uddg;
             }

             if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(rawUrl))
                 continue;

             results.Add(new SearchResult(title, rawUrl));
             if (results.Count >= 5)
                 break;
         }

         return results;
     }

     private static string StripHtml(string html)
     {
         // Remove script/style blocks, then tags, then collapse whitespace.
         var noScripts = ScriptStyleRegex().Replace(html, " ");
         var noTags = StripHtmlTags(noScripts);
         var collapsed = WhitespaceRegex().Replace(noTags, " ");
         return WebUtility.HtmlDecode(collapsed).Trim();
     }

     private static string StripHtmlTags(string input) =>
         TagRegex().Replace(input, string.Empty);

     [GeneratedRegex("""<a[^>]+class="[^"]*result__a[^"]*"[^>]+href="(?<url>[^"]+)"[^>]*>(?<title>.*?)</a>""",
         RegexOptions.Singleline | RegexOptions.IgnoreCase)]
     private static partial Regex ResultLinkRegex();

     [GeneratedRegex("""<(script|style)[^>]*>.*?</\1>""",
         RegexOptions.Singleline | RegexOptions.IgnoreCase)]
     private static partial Regex ScriptStyleRegex();

     [GeneratedRegex("""<[^>]+>""")]
     private static partial Regex TagRegex();

     [GeneratedRegex("""\s+""")]
     private static partial Regex WhitespaceRegex();
 }

 public sealed record SearchResult(
     [property: Description("Title of the search result")] string Title,
     [property: Description("URL of the search result")] string Url);

